// Role toolsets with authority rationale (plain JS manifest)
const TOOLSETS = {
  triage: ["read_ticket"],                                   // reads only
  researcher: ["read_ticket", "search_catalog"],              // reads + lookup
  drafter: ["read_decision"],                                 // writes text only
  finance: ["read_decision", "issue_refund@gated"],           // money: gated flag
  logger: ["append_record"],                                  // append-only
};
// Audit rule: any write/money tool outside its mandate role is a finding.
// @gated suffix marks tools requiring approval-gate passage.

// Toolset audit: out-of-mandate powers flagged (plain JS)
const POWERS = { read_ticket: 1, search_catalog: 1, read_decision: 1, append_record: 1, issue_refund: 3, delete_user: 3 };
function auditToolsets(toolsets) {
  const findings = [];
  for (const [role, tools] of Object.entries(toolsets)) {
    for (const t of tools) {
      const base = t.replace(/@gated$/, "");
      if ((POWERS[base] || 0) >= 3 && !t.endsWith("@gated") && role !== "finance")
        findings.push(`${role} holds ungated power tool: ${base}`);
      if (role === "support-drafter" && base !== "read_decision")
        findings.push(`drafter holds non-draft tool: ${base}`);
    }
  }
  return findings;
}
// Power levels + gating suffixes make audits mechanical; judgment stays human.

